const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateFormatters=new Map();
const fmt=(iso,opts)=>{const key=JSON.stringify(opts);if(!dateFormatters.has(key))dateFormatters.set(key,new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',...opts}));return dateFormatters.get(key).format(new Date(iso));};
const day=iso=>fmt(iso,{day:'numeric',month:'short'});
const hour=iso=>fmt(iso,{hour:'2-digit',minute:'2-digit'});
const dayKey=iso=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso));
const nextStart=()=>new Date((Math.floor(Date.now()/3600000)+1)*3600000);
const nextStartDate=()=>dayKey(nextStart());
const nextStartTime=()=>hour(nextStart());
const addHours=(iso,h)=>hour(new Date(new Date(iso).getTime()+h*3600000));
const requestDefaultStart=()=>{const d=nextStart();return hour(d).startsWith('23:')?new Date(d.getTime()+9*3600000):d;};
const requestDefaultEnd=()=>addHours(requestDefaultStart(),hour(requestDefaultStart()).startsWith('22:')?1:2);
const infoTip=message=>`<span class="info-tip" tabindex="0" role="note" aria-label="${esc(message)}">i<span class="info-tip-text">${esc(message)}</span></span>`;
