function headers(){return tg?.initData?{'Authorization':'tma '+tg.initData}:state.config.demo?{'X-Demo-User':demoId,'X-Demo-Name':encodeURIComponent('Роман')}:(state.webCsrf?{'X-Web-CSRF':state.webCsrf}:{});}
async function api(route,method='GET',payload){const chatRequest=/^\/(inbox|direct|chats|dialogs)(\/|\?|$)/.test(route);try{const res=await fetch('/api'+route,{signal:chatRequest&&typeof AbortSignal!=='undefined'&&AbortSignal.timeout?AbortSignal.timeout(15000):undefined,method,headers:{...headers(),...(payload?{'Content-Type':'application/json'}:{})},body:payload?JSON.stringify(payload):undefined});const data=await res.json();if(!res.ok){if(res.status===401&&!tg?.initData&&!state.config.demo&&!route.startsWith('/web-auth/')&&route!=='/config'){state.me=null;webEntry('Сессия истекла. Войдите снова.');}throw new Error(data.error||'Ошибка сети');}return data;}catch(error){if(chatRequest&&['TimeoutError','AbortError'].includes(error.name))throw new Error('Чат не ответил вовремя. Попробуйте ещё раз');throw error;}}
function toast(message){document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),3300);tg?.HapticFeedback?.notificationOccurred?.('success');}
function listingLink(kind,id){const start=`${kind}_${id}`,bot=state.config.botUsername?.replace(/^@/,'');return bot&&tg?.initData?`https://t.me/${bot}?startapp=${start}`:`${location.origin}/?start=${encodeURIComponent(start)}`;}
async function shareListing(kind,id,copy=false){const url=listingLink(kind,id),title=kind==='game'?'Игра в Tennis GO':'Тренировка в Tennis GO';if(!copy&&navigator.share){try{await navigator.share({title,url});return;}catch(err){if(err.name==='AbortError')return;}}if(!copy&&tg?.openTelegramLink){tg.openTelegramLink(`https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(title)}`);return;}await navigator.clipboard.writeText(url);toast('Ссылка скопирована');}
async function refresh(){const previousSport=preferredSport();const me=(await api('/me')).user;state.me=me;if(previousSport!==preferredSport())syncSportFilters();if(me.role==='club'&&!me.isAdmin){state.clubDate ||= dayKey(Date.now());const data=await api('/club/calendar?date='+state.clubDate);state.clubCalendar=data.reservations||[];return;}const [g,c,t,r,i,n,h,p,b,event,news,polls,friends,feedback]=await Promise.all([api('/games'),api('/catalog'),api('/trainings'),api('/training-requests'),api('/inbox'),api('/notifications'),api('/ratings/history'),api('/progress'),api('/court-bookings'),api('/events/marathon'),api('/news'),api('/match-polls'),api('/friends').catch(()=>({accepted:[],incoming:[],outgoing:[]})),api('/feedback/pending')]);state.friends=friends;state.games=g.games;state.pendingVotes=polls.games||[];state.pendingFeedback=feedback.games||[];state.catalog=c;state.trainings=t.trainings;state.trainingRequests=r.requests||[];state.inbox=i.threads||[];state.inboxMore=!!i.hasMore;state.unread=i.unread||0;state.notifications=n.items||[];state.notificationUnread=n.unread||0;state.ratingHistory=h.events||[];state.progress=p;state.clubBookings=b.bookings||[];state.marathon=event;state.news=news.items||[];state.rewards=state.news.find(n=>n.campaign)?.campaign||state.rewards;if(state.rewards)state.marathon=null;if(!state.weatherFetched){state.weatherFetched=true;loadWeather();}}
async function loadWeather(){try{const city=state.cityFilter!=='all'?state.cityFilter:state.trainingCity!=='all'?state.trainingCity:'Краснодар';const w=await api('/weather?city='+encodeURIComponent(city));state.weatherCity=city;state.weather=w.hours||[];state.weatherStatus=w.status||'unavailable';}catch{state.weather=[];state.weatherStatus='unavailable';}if(!state.loading&&state.me?.registered&&!state.form&&!state.chat)render();}
let inboxInFlight=null;
async function loadInbox(updatePage=true,more=false){
 if(inboxInFlight){await inboxInFlight;if(more)return loadInbox(updatePage,true);return;}
 state.inboxLoading=true;
 inboxInFlight=(async()=>{try{
  const data=await api('/inbox?limit='+ (more?50:Math.min(200,Math.max(50,state.inbox.length)))+'&offset='+(more?state.inbox.length:0));
  const before=JSON.stringify(state.inbox),old=state.inbox;
  const head=data.threads||[];state.inbox=more?[...old,...head.filter(t=>!old.some(x=>x.key===t.key))]:[...head,...(old.length>200?old.slice(200).filter(t=>!head.some(x=>x.key===t.key)):[])];
  if(more||old.length<=200)state.inboxMore=!!data.hasMore;state.unread=data.unread||0;
  const badge=document.querySelector('#chat-badge');if(badge){badge.textContent=state.unread||'';badge.hidden=!state.unread;}
  if(updatePage&&state.tab==='chat'&&!state.chat&&before!==JSON.stringify(state.inbox))render();
 }finally{state.inboxLoading=false;inboxInFlight=null;}})();
 return inboxInFlight;
}
async function loadPeople(reset=false){const offset=reset?0:state.peopleOffset,search=state.peopleQuery,mode=state.peopleMode;const data=await api('/users?q='+encodeURIComponent(search)+'&offset='+offset+(mode==='coach'?'&role=coach':''));if(search!==state.peopleQuery||mode!==state.peopleMode)return;state.people=reset?data.users:[...state.people,...data.users];state.peopleOffset=offset+data.users.length;state.peopleMore=!!data.hasMore;render();}
