async function loadAdmin(tab=state.adminTab){if(!state.me?.isAdmin)return;state.adminTab=tab;if(tab==='rewards')state.rewardAdmin=await api('/rewards/admin');else if(tab==='overview')state.adminStats=await api('/admin/stats');else if(tab==='users')state.adminUsers=(await api('/admin/users?q='+encodeURIComponent(state.adminQuery))).users;else if(tab==='messages')state.adminMessages=(await api('/admin/messages')).messages;else if(tab==='clubs')state.adminClubs=(await api('/admin/clubs')).clubs;else if(['games','trainings'].includes(tab))state.adminListings=await api('/admin/listings');}
const avatarChoices=[['male-serve','Подача','Мужские'],['male-cap','Кепка','Мужские'],['male-court','У сетки','Мужские'],['female-serve','Подача','Женские'],['female-cap','Козырёк','Женские'],['female-court','У сетки','Женские']];
function tennisAvatar(id){return `<span class="tennis-avatar avatar-sprite avatar-${id}" role="img" aria-label="Мультяшная теннисная аватарка"></span>`;}
function avatar(u){return u?.photoData?`<img src="${esc(u.photoData)}" alt="Фото профиля" loading="lazy" decoding="async">`:u?.avatarId&&avatarChoices.some(([id])=>id===u.avatarId)?tennisAvatar(u.avatarId):esc((u?.name||'Р').slice(0,1).toUpperCase());}
