function personalReputation(u){return `<section class="profile-section"><h2>Личные данные</h2>${reputationCard(u.reputation??5,'Репутация',u.reputationCount?`${u.reputationCount} оценок · максимум 5.00`:'Пока нет оценок · начальная репутация 5.00')}<span class="profile-subline">Репутация пересчитывается по полученным оценкам после игр и тренировок.</span></section>`;}
function gameFeedbackForm(g){if(!g||g.cancelled||!g.joined||g.members.length<2||Date.parse(g.startsAt)+g.duration*60000>Date.now())return '';if(g.feedbackSubmitted)return '<p class="notice">✓ Вы оценили эту игру. Оценка учтена в репутации участников.</p>';return `<form id="game-feedback-form" data-game-id="${esc(g.id)}" class="form-card feedback-form"><h3>Оцените игру</h3><fieldset class="feedback-fieldset"><legend>Оценка от 1 до 5</legend><div class="feedback-scores">${[1,2,3,4,5].map(score=>`<label><input type="radio" name="score" value="${score}" required><span>${score}</span></label>`).join('')}</div></fieldset><p class="hint">Поставьте 1, если оппонент не пришёл на игру.</p><p class="hint">Оценка зачтётся остальным участникам игры. В парной игре её получат все остальные игроки.</p><label class="field">Комментарий · по желанию<textarea name="comment" maxlength="500" placeholder="Как прошла игра?"></textarea></label><button class="button" type="submit">Отправить оценку</button></form>`;}
function pendingFeedbackPanel(){return state.pendingFeedback.length?`<section class="home-section feedback-pending"><div class="section-head"><h2>Оцените игру</h2><span class="muted">${state.pendingFeedback.length}</span></div>${state.pendingFeedback.slice(0,3).map(g=>`<div class="card feedback-pending-game"><div><strong>${esc(g.venue)}</strong><small>${day(g.startsAt)} · ${hour(g.startsAt)}</small></div><button class="small-btn" type="button" data-feedback-game="${esc(g.id)}">Оцените игру</button></div>`).join('')}${state.pendingFeedback.length>3?'<p class="hint">После оценки появятся следующие игры.</p>':''}</section>`:'';}
function gameFeedbackPage(){const g=state.feedbackGame;return `<div class="content subpage"><h1 class="page-title">Оцените игру</h1>${g?`<p class="lead">${esc(g.venue)} · ${day(g.startsAt)} · ${hour(g.startsAt)}</p>${gameFeedbackForm(g)}`:'<p class="notice">Игра не найдена</p>'}</div>`;}
function participantRows(members){return members.length?members.map(m=>`<button class="participant-row" data-user="${esc(m.id)}"><span class="avatar">${avatar(m)}</span><span class="participant-person"><strong>${esc(m.name)}</strong>${m.reputation==null?'':reputationBadge(m.reputation)}</span><span class="participant-next">Профиль →</span></button>`).join(''):'<p class="muted">Пока никто не записался.</p>';}
function requestPanel(kind,item){const requests=item.requests||[];return requests.length?`<div class="form-card join-requests"><h3>Заявки на участие · ${requests.length}</h3>${requests.map(user=>`<div class="request-row"><button class="request-person" data-user="${esc(user.id)}"><span class="avatar">${avatar(user)}</span>${esc(user.name)}</button><span class="request-actions"><button class="small-btn" data-request-decision="approve" data-request-kind="${kind}" data-request-id="${esc(item.id)}" data-request-user="${esc(user.id)}">Принять</button><button class="small-btn outline" data-request-decision="reject" data-request-kind="${kind}" data-request-id="${esc(item.id)}" data-request-user="${esc(user.id)}">Отклонить</button></span></div>`).join('')}</div>`:'';}
