function logo(){const city=esc(state.me?.city||'Краснодар'),canChoose=!!state.me?.registered&&(state.me.role!=='club'||state.me.isAdmin),hasActions=state.me?.registered&&state.me.role!=='club';return `<header class="top"><span class="brand-logo"><img class="brand-symbol" src="/assets/tennis-go-logo-4-symbol.png" alt=""><img class="brand-wordmark" src="/assets/tennis-go-logo-4-wordmark.png" alt="Tennis GO"></span><div class="top-actions">${hasActions?`<button class="notification-button" data-notifications aria-label="Уведомления">🔔${state.notificationUnread?`<b>${state.notificationUnread}</b>`:''}</button><button class="top-avatar" type="button" data-tab="profile" aria-label="Открыть мой профиль"><span class="avatar">${avatar(state.me)}</span></button>`:`<span class="avatar">${avatar(state.me)}</span>`}</div><span class="top-city-wrap">${canChoose?`<button class="city-pill city-trigger" type="button" data-city-menu aria-expanded="${state.cityMenuOpen}" aria-label="Выбрать город, сейчас ${city}" title="${city}">⌖ ${city} ▾</button>`:`<span class="city-pill" title="${city}">⌖ ${city}</span>`}${canChoose&&state.cityMenuOpen?`<label class="top-city-popover">Ваш город<select id="top-city-select" aria-label="Выберите город">${(state.config.cities||['Краснодар']).map(c=>`<option value="${esc(c)}" ${c===state.me.city?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`:''}</span></header>`;}
function nav(){const ball='<svg viewBox="0 0 24 24" aria-hidden="true"><defs><radialGradient id="tennis-ball-yellow" cx="36%" cy="29%" r="74%"><stop stop-color="#f8ff9d"/><stop offset=".48" stop-color="#e5f641"/><stop offset="1" stop-color="#b4d329"/></radialGradient></defs><circle cx="12" cy="12" r="9" fill="url(#tennis-ball-yellow)" stroke="#98ac28" stroke-width=".65"/><path d="M6.2 5.1c4.4 3.8 4.4 10 0 13.8M17.8 5.1c-4.4 3.8-4.4 10 0 13.8" fill="none" stroke="#fffdf0" stroke-width="1.65" stroke-linecap="round"/></svg>',bubble='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20 11.5a8 8 0 0 1-8 8 9 9 0 0 1-3.8-.8L4 20l1.3-4.2A8 8 0 1 1 20 11.5Z"/><path d="M8 11.5h8"/></svg>';return `<nav class="nav" aria-label="Основное меню">${[['home','⌂','Главная'],['play',ball,'Играть'],['chat',bubble,'Чат'],['profile','<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="7.5" r="3.5"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg>','Профиль']].map(([id,icon,label])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}"><i>${icon}</i>${label}${id==='chat'?`<span id="chat-badge" class="nav-unread" ${state.unread?'':'hidden'}>${state.unread||''}</span>`:''}</button>`).join('')}</nav>`;}
