let feedbackPollBusy=false;
async function pollFeedback(){
  if(feedbackPollBusy||!state.me?.registered||state.me.blockedAt||state.me.role==='club')return;
  feedbackPollBusy=true;
  try{
    const data=await api('/feedback/pending'),games=data.games||[],changed=JSON.stringify(games)!==JSON.stringify(state.pendingFeedback);
    state.pendingFeedback=games;
    if(changed&&!state.form&&!state.chat&&!state.detail&&!state.trainingDetail&&!state.userProfile&&['home','profile'].includes(state.tab))render();
  }catch{}finally{feedbackPollBusy=false;}
}
window.setInterval?.(pollFeedback,30000);
document.addEventListener?.('visibilitychange',()=>{if(document.visibilityState==='visible')pollFeedback();});

let rewardPollBusy=false;
async function pollRewards(){if(rewardPollBusy||document.visibilityState==='hidden'||!state.me?.registered||state.me.role==='club'||state.me.blockedAt)return;const visible=state.form==='news'||state.form==='rewards'||!state.form&&(state.tab==='home'||state.tab==='community'&&['events','rating'].includes(state.communityTab));if(!visible||state.chat||state.detail||state.trainingDetail||state.userProfile)return;rewardPollBusy=true;try{const c=await api('/rewards');state.rewards=c;state.news=state.news.map(n=>n.id===c.id?{...n,campaign:c}:n);if(state.tab==='community'&&state.communityTab==='rating'){const data=await api('/leaderboard?sport='+state.leaderboardSport+'&mode='+state.leaderboardMode);state.leaderboard=data.players||[];}const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(!typing)render();}catch{}finally{rewardPollBusy=false;}}
window.setInterval?.(pollRewards,30000);

let syncRevision=null,syncBusy=false,syncDeferred=false;
async function pollDataSync(){
 if(syncBusy||document.visibilityState==='hidden'||!state.me?.registered||state.me.blockedAt)return;
 syncBusy=true;
 try{const data=await api('/sync');if(data.revision===syncRevision&&!syncDeferred)return;syncRevision=data.revision;
 const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName),safeForm=!state.form||['news','rewards','notifications','my-rating'].includes(state.form);
 if(editing||!safeForm||state.chat||state.userProfile){syncDeferred=true;return;}
 syncDeferred=false;const view=[state.tab,state.form,state.detail?.id,state.trainingDetail?.id].join('|'),gameId=state.detail?.id,trainingId=state.trainingDetail?.id;
 await refresh();if(view!==[state.tab,state.form,state.detail?.id,state.trainingDetail?.id].join('|'))return;
 if(gameId)state.detail=(await api('/games/'+gameId)).game;if(trainingId)state.trainingDetail=(await api('/trainings/'+trainingId)).training;
 if(state.tab==='community'&&state.communityTab==='rating'){const r=await api('/leaderboard?sport='+state.leaderboardSport+'&mode='+state.leaderboardMode);state.leaderboard=r.players||[];}
 if(!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render();
 }catch{syncDeferred=true;}finally{syncBusy=false;}
}
window.setInterval?.(pollDataSync,20000);
